input.content:
/* Base layout */
* {
  box-sizing: border-box;
}

html,
body {
  margin: 0;
  padding: 0;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica,
    Arial, sans-serif;
  background: #f4f6f8;
  color: #1f2933;
}

header {
  padding: 18px 28px 8px;
  background: #ffffff;
  border-bottom: 1px solid #e3e8ee;
}

header h1 {
  margin: 0;
  font-size: 22px;
  font-weight: 600;
  color: #102a43;
}

header p {
  margin: 4px 0 0;
  color: #5b6b7b;
  font-size: 13px;
}

main {
  display: flex;
  flex-direction: row;
  gap: 16px;
  padding: 16px;
  align-items: flex-start;
}

#chart-section {
  flex: 1 1 auto;
  min-width: 0;
  background: #ffffff;
  border-radius: 10px;
  border: 1px solid #e3e8ee;
  padding: 12px 16px 8px;
  position: relative;
}

#table-section {
  flex: 1 1 auto;
  min-width: 0;
  background: #ffffff;
  border-radius: 10px;
  border: 1px solid #e3e8ee;
  padding: 12px 16px 16px;
}

.section-title {
  font-size: 14px;
  font-weight: 600;
  color: #334e68;
  margin: 0 0 6px;
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

#bubble-chart {
  width: 100%;
  height: 620px;
  display: block;
}

/* Tooltip */
.tooltip {
  position: absolute;
  pointer-events: none;
  background: rgba(16, 42, 67, 0.95);
  color: #ffffff;
  padding: 8px 12px;
  border-radius: 6px;
  font-size: 12px;
  line-height: 1.45;
  box-shadow: 0 4px 14px rgba(15, 23, 42, 0.25);
  opacity: 0;
  transition: opacity 0.12s ease-out;
  z-index: 10;
  max-width: 260px;
}

.tooltip strong {
  color: #ffffff;
}

.tooltip .tooltip-ticker {
  font-size: 14px;
  font-weight: 600;
  letter-spacing: 0.04em;
}

.tooltip .tooltip-label {
  color: #bcccdc;
}

/* Bubble labels */
.bubble-label {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica,
    Arial, sans-serif;
  pointer-events: none;
  user-select: none;
  font-weight: 600;
  fill: #ffffff;
  text-anchor: middle;
  dominant-baseline: central;
}

.bubble {
  cursor: pointer;
  stroke: #ffffff;
  stroke-width: 1.5;
  transition: stroke-width 0.12s ease-out, stroke 0.12s ease-out,
    opacity 0.12s ease-out;
}

.bubble.dim {
  opacity: 0.25;
}

.bubble.active {
  stroke: #102a43;
  stroke-width: 3;
}

/* Legend */
.legend {
  display: flex;
  flex-wrap: wrap;
  gap: 10px 18px;
  margin: 8px 2px 0;
  font-size: 12px;
  color: #334e68;
}

.legend-item {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.legend-swatch {
  width: 12px;
  height: 12px;
  border-radius: 50%;
  display: inline-block;
  border: 1px solid #ffffff;
  box-shadow: 0 0 0 1px rgba(15, 23, 42, 0.18);
}

/* Table */
.table-wrap {
  max-height: 600px;
  overflow-y: auto;
  border: 1px solid #e3e8ee;
  border-radius: 8px;
}

#stocks-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 13px;
}

#stocks-table thead th {
  position: sticky;
  top: 0;
  background: #f0f4f8;
  color: #334e68;
  text-align: left;
  padding: 10px 12px;
  font-weight: 600;
  border-bottom: 1px solid #d9e2ec;
  text-transform: uppercase;
  font-size: 11px;
  letter-spacing: 0.05em;
}

#stocks-table tbody td {
  padding: 8px 12px;
  border-bottom: 1px solid #eef2f6;
  vertical-align: middle;
}

#stocks-table tbody tr {
  cursor: pointer;
  transition: background-color 0.12s ease-out;
}

#stocks-table tbody tr:hover {
  background: #f4f8fc;
}

#stocks-table tbody tr.selected {
  background: #d9e8ff;
}

#stocks-table tbody tr.selected td {
  font-weight: 600;
  color: #143a7a;
}

.ticker-cell {
  font-weight: 600;
  color: #102a43;
  letter-spacing: 0.02em;
}

.sector-cell {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.sector-cell .legend-swatch {
  width: 10px;
  height: 10px;
}

.market-cap-cell {
  font-variant-numeric: tabular-nums;
  text-align: right;
  color: #486581;
}

.muted {
  color: #9aa5b1;
}

@media (max-width: 1000px) {
  main {
    flex-direction: column;
  }
}

